mapper.select:
SELECT  
AND e.status=#{query.status,javaType=com.equipops.domain.enums.AlertEventStatus,typeHandler=org.apache.ibatis.type.EnumTypeHandler}
AND e.recovery_status=#{query.recoveryStatus,javaType=com.equipops.domain.enums.AlertRecoveryStatus,typeHandler=org.apache.ibatis.type.EnumTypeHandler}
AND e.rule_id=#{query.ruleId}
ORDER BY e.created_at DESC,e.id DESC
